 const missing={visualInputs:[inputs[1]]};await assert.rejects(()=>verifyWebVisualInputs(root,missing,missing,source,figures),/unique_original/);const wrong=structuredClone(call);wrong.visualInputs[1].scale=3;await assert.rejects(()=>verifyWebVisualInputs(root,wrong,wrong,source,figures),/invalid_zoom/);const paint=spawnSync('python',['-c',"from PIL import Image\nimport sys\na=Image.open(sys.argv[1]);a.putpixel((0,0),(0,255,0,255));a.save(sys.argv[1])",z]);assert.equal(paint.status,0,String(paint.stderr));inputs[1].sha256=sha(await readFile(z));await assert.rejects(()=>verifyWebVisualInputs(root,call,call,source,figures),/not_exact_nearest_pixels/);
