async function diskFixture(root){
 const put=async(path,value)=>{await mkdir(dirname(join(root,path)),{recursive:true});await writeFile(join(root,path),typeof value==='string'||Buffer.isBuffer(value)?value:JSON.stringify(value));};
 const html='<div id="main"><p><strong>通常可以</strong>，但对子多时例外。</p></div>',htmlPath='fixture/html/source.html',mainPath='fixture/main.html';
 const source={schema:'coach-textbook-web-article-source/1',sourceId:'fixture-cn',articleId:'chapter',url:'https://example.test/chapter',title:'条件和例外',language:'zh-CN',fetchedAt:'2026-01-01T00:00:00Z',html:{path:htmlPath,sha256:sha(html),encoding:'utf-8'},main:{selector:'#main',path:mainPath,sha256:sha(html)},blocks:[{id:'b1',type:'text',text:'通常可以，但对子多时例外。',segments:[{text:'通常可以',marks:['strong::'],href:null},{text:'，但对子多时例外。',marks:[],href:null}],paragraphId:'p1',tableContext:null}],assets:[],ignoredPlaceholders:[],extractorSha256:'extractor',status:'captured-not-translated-or-audited'};
 const sourcePath='web-sources/v1/fixture/source.json';await put('web-sources/v1/'+htmlPath,html);await put('web-sources/v1/'+mainPath,html);await put(sourcePath,source);const sourceFileSha256=sha(await readFile(join(root,sourcePath)));
 const reuse={schema:'coach-textbook-exact-web-reuse/1',sourceFileSha256,images:[]};await put('integration/reuse.json',reuse);
 const candidate={schema:'coach-textbook-web-article-draft/1',status:'draft',source:{sourceId:source.sourceId,articleId:source.articleId,url:source.url,title:source.title,language:source.language,fetchedAt:source.fetchedAt,sourcePath,sourceSha256:sourceFileSha256,htmlSha256:sha(html),mainSha256:sha(html)},body:{language:'zh-CN',mode:'verbatim',flowOrder:'source-dom-order',blocks:[{type:'text',sourceBlockIds:['b1'],sourceText:source.blocks[0].text,text:source.blocks[0].text,paragraphId:'p1',tableContext:null,sourceSegments:source.blocks[0].segments}]},figures:[],provenance:{model:null,reasoningEffort:null,modelCalls:0,attempts:[],usage:null,extractorSha256:'extractor',reuseMap:{path:'integration/reuse.json',sha256:sha(await readFile(join(root,'integration/reuse.json')))}}};
 const candidatePath='web-production/v1/candidates/fixture-cn/chapter.json';await put(candidatePath,seal(candidate));return {put,source,candidate,candidatePath,sourcePath,html,mainPath};
}

